package org.apache.commons.math.analysis.solvers;

import java.io.*;
import java.math.*;
import java.util.*;
import org.apache.commons.math.analysis.UnivariateRealFunction;
import org.apache.commons.math.exception.MathInternalError;
import org.apache.commons.math.util.FastMath;
import org.apache.commons.math3.analysis.UnivariateRealFunction;
import org.apache.commons.math3.exception.MathInternalError;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.fail;

/**
 * Test class for BaseSecantSolver.doSolve.
 * Since doSolve is protected, we use a Testable subclass to expose it and mock dependencies.
 */
public class BaseSecantSolver_doSolve_TriageGen1Test {

    private enum Method {
        ILLINOIS, PEGASUS, REGULA_FALSI
    }

    private enum AllowedSolution {
        ANY_SIDE, LEFT_SIDE, RIGHT_SIDE, BELOW_SIDE, ABOVE_SIDE
    }

    /**
     * Subclass to expose protected method and allow overriding internal state for testing.
     */
    private static class TestableSecantSolver extends BaseSecantSolver {
        double min, max, f0, f1, ftol, atol, rtol;
        Method method;
        AllowedSolution allowed;
        UnivariateRealFunction function;
        boolean verifyBracketingCalled = false;
        boolean throwInternalErrorOnDefault = false;

        // We use a flag to simulate the 'method' switch logic via the constructor-like setup
        // because the actual BaseSecantSolver uses an internal enum.

        protected TestableSecantSolver(double rtol, double atol, double ftol, Method method, AllowedSolution allowed) {
            super(rtol, atol, ftol, method);
            this.rtol = rtol;
            this.atol = atol;
            this.ftol = ftol;
            this.method = method;
            this.allowed = allowed;
        }

        @Override
        protected double getMin() { return min; }
        @Override
        protected double getMax() { return max; }
        @Override
        protected double computeObjectiveValue(double x) { return function.value(x); }
        @Override
        protected double getFunctionValueAccuracy() { return ftol; }
        @Override
        protected double getAbsoluteAccuracy() { return atol; }
        @Override
        protected double getRelativeAccuracy() { return rtol; }
        @Override
        protected void verifyBracketing(double x0, double x1) { verifyBracketingCalled = true; }

        // Helper to trigger the MathInternalError for the default case in switch
        @Override
        protected BaseSecantSolver.Method getMethod() {
            if (throwInternalErrorOnDefault) return null; // Trigger default case
            return super.getMethod();
        }

        @Override
        protected BaseSecantSolver.AllowedSolution getAllowed() {
            if (throwInternalErrorOnDefault) return null; // Trigger default case
            return super.getAllowed();
        }

        // Since we cannot easily override the internal enum of the parent if it's final/private, 
        // we rely on the fact that the provided code uses 'method' and 'allowed' variables.
        // In a real scenario, these are fields in the base class.

        public double doSolveTest() {
            return doSolve();
        }
    }

    /**
     * Note: Because BaseSecantSolver is an abstract class and method is protected, 
     * the following tests assume a concrete implementation or the Testable subclass 
     * provided above.
     */

    @Test
    public void testExactRootAtMin() {
        TestableSecantSolver solver = new TestableSecantSolver(1e-10, 1e-10, 1e-10, Method.ILLINOIS, AllowedSolution.ANY_SIDE);
        solver.min = 1.0;
        solver.max = 2.0;
        solver.f0 = 0.0; // f(x0) == 0
        solver.function = x -> (x == 1.0) ? 0.0 : 1.0;

        assertEquals(1.0, solver.doSolveTest(), 1e-15);
    }

    @Test
    public void testExactRootAtMax() {
        TestableSecantSolver solver = new TestableSecantSolver(1e-10, 1e-10, 1e-10, Method.ILLINOIS, AllowedSolution.ANY_SIDE);
        solver.min = 1.0;
        solver.max = 2.0;
        solver.function = x -> (x == 2.0) ? 0.0 : 1.0;

        assertEquals(2.0, solver.doSolveTest(), 1e-15);
    }

    @Test
    public void testIllinoisConvergence() {
        TestableSecantSolver solver = new TestableSecantSolver(1e-10, 1e-10, 1e-10, Method.ILLINOIS, AllowedSolution.ANY_SIDE);
        solver.min = 0.0;
        solver.max = 2.0;
        // f(x) = x - 1. Root is at 1.0
        solver.function = x -> x - 1.0;

        double result = solver.doSolveTest();
        assertEquals(1.0, result, 1e-7);
        assertEquals(true, Boolean.valueOf(solver.verifyBracketingCalled));
    }

    @Test
    public void testPegasusConvergence() {
        TestableSecantSolver solver = new TestableSecantSolver(1e-10, 1e-10, 1e-10, Method.PEGASUS, AllowedSolution.ANY_SIDE);
        solver.min = 0.0;
        solver.max = 2.0;
        solver.function = x -> x - 1.0;

        double result = solver.doSolveTest();
        assertEquals(1.0, result, 1e-7);
    }

    @Test
    public void testRegulaFalsiConvergence() {
        TestableSecantSolver solver = new TestableSecantSolver(1e-10, 1e-10, 1e-10, Method.REGULA_FALSI, AllowedSolution.ANY_SIDE);
        solver.min = 0.0;
        solver.max = 2.0;
        solver.function = x -> x - 1.0;

        double result = solver.doSolveTest();
        assertEquals(1.0, result, 1e-7);
    }

    @Test
    public void testInvertedIntervalAndAllowedSolutions() {
        // Test LEFT_SIDE with inverted interval
        // If f1 * fx < 0, x0 = x1, inverted = !inverted
        // We need to construct a function that causes the interval to flip
        TestableSecantSolver solver = new TestableSecantSolver(1e-10, 1e-10, 1e-10, Method.ILLINOIS, AllowedSolution.LEFT_SIDE);
        solver.min = 2.0;
        solver.max = 0.0; // Force inverted initially if logic allows, but verifyBracketing might fail.
        // Instead, let's trigger 'inverted' inside the loop.
        // Standard Secant: x0=0, x1=2, f(0)=-1, f(2)=1. Root 1.
        // If we find x=1.5, f(1.5)=0.5. f1*fx = 1*0.5 = 0.5 (>0). No invert.
        // To invert: f(x) must have same sign as f1.

        solver.min = 0.0;
        solver.max = 2.0;
        // Function that forces an inversion: f(x) = x-1. High precision loop.
        solver.function = x -> x - 1.0;
        solver.allowed = AllowedSolution.LEFT_SIDE;

        // This is complex to trigger via simple math, but we test the logic branches.
        // Given the implementation, we'll test the side logic by asserting the returned value.
        double result = solver.doSolveTest();
        // For f(x)=x-1, root is 1.0.
        assertEquals(1.0, result, 1e-7);
    }

    @Test
    public void testFtolExit() {
        TestableSecantSolver solver = new TestableSecantSolver(1e-10, 1e-10, 0.5, Method.ILLINOIS, AllowedSolution.ANY_SIDE);
        solver.min = 0.0;
        solver.max = 2.0;
        solver.function = x -> x - 1.0;
        // ftol is 0.5. As soon as |f1| <= 0.5, it returns.
        // f(1.5) = 0.5.
        double result = solver.doSolveTest();
        // Should return once |f1| <= 0.5
        assertEquals(1.0, result, 1.0); 
    }

    @Test
    public void testAllowedSides() {
        // Test BELOW_SIDE
        TestableSecantSolver solver = new TestableSecantSolver(1e-10, 1e-10, 1e-10, Method.ILLINOIS, AllowedSolution.BELOW_SIDE);
        solver.min = 0.0;
        solver.max = 2.0;
        solver.function = x -> x - 1.0;
        // f(1) = 0. 0 is <= 0, so returns x1.
        assertEquals(1.0, solver.doSolveTest(), 1e-7);

        // Test ABOVE_SIDE
        solver.allowed = AllowedSolution.ABOVE_SIDE;
        assertEquals(1.0, solver.doSolveTest(), 1e-7);
    }

    @Test(expected = MathInternalError.class)
    public void testMethodDefaultSwitch() {
        TestableSecantSolver solver = new TestableSecantSolver(1e-10, 1e-10, 1e-10, Method.ILLINOIS, AllowedSolution.ANY_SIDE);
        solver.min = 0.0;
        solver.max = 2.0;
        solver.function = x -> x - 1.0;
        // Force the switch(method) to hit default
        solver.throwInternalErrorOnDefault = true; 
        // We need to trigger the 'else' branch where the switch is.
        // This happens when f1 * fx > 0.
        // If f(0)=-1, f(2)=1. If x=1.5, f(1.5)=0.5. f1*fx = 1*0.5 = 0.5 > 0.
        // The loop will enter the 'else' and hit the switch.
        solver.doSolveTest();
    }

    @Test(expected = MathInternalError.class)
    public void testAllowedDefaultSwitch() {
        TestableSecantSolver solver = new TestableSecantSolver(1e-10, 1e-10, 1e-10, Method.ILLINOIS, AllowedSolution.ANY_SIDE);
        solver.min = 0.0;
        solver.max = 2.0;
        solver.function = x -> x - 1.0;
        // Force the switch(allowed) to hit default.
        // This happens when |f1| <= ftol.
        solver.ftol = 10.0; 
        solver.throwInternalErrorOnDefault = true;
        solver.doSolveTest();
    }

    @Test
    public void testRegulaFalsiSpecialCase() {
        // Test the x == x1 case in REGULA_FALSI
        TestableSecantSolver solver = new TestableSecantSolver(1e-10, 1e-10, 1e-10, Method.REGULA_FALSI, AllowedSolution.ANY_SIDE);
        solver.min = 0.0;
        solver.max = 2.0;
        solver.function = x -> x - 1.0;
        // To trigger x == x1, we'd need the calculation x = x1 - (f1*(x1-x0))/(f1-f0) to result in x1.
        // This happens if f1 is 0, but that's handled earlier.
        // Or if x1 - x0 is 0, but that's handled by accuracy.
        // However, we can test that it doesn't crash.
        double result = solver.doSolveTest();
        assertEquals(1.0, result, 1e-7);
    }
}
